use super::*;

#[test]
fn malformed_create_table_elements_are_rejected() {
    assert_parse_errors(&[
        "create table t (id)",
        "create table t (id int,)",
        "create table t (id int default)",
        "create table t (id int constraint named)",
        "create table t (id int collate)",
        "create table t (id int generated by default as (id + 1))",
        "create table t (id int generated always as identity ())",
        "create table t (id int generated by default as identity ())",
        "create table t (id int references)",
        "create table t (id int references parent())",
        "create table t (id int references parent(id) on delete)",
        "create table t (constraint c check ())",
        "create table t (unique ())",
        "create table t (primary (id))",
        "create table t (foreign key () references parent(id))",
        "create table t (foreign key (id) references)",
        "create table t (foreign key (id) references parent(id) match partial)",
        "create table t (check (id > 0) deferrable)",
        "create table t (not null id enforced)",
        "create table t (unique (id) not valid)",
        "create table t (unique nulls distinct using index idx)",
        "create table t (unique nulls not distinct using index idx)",
        "create table t (unique (lower(id)))",
        "create table t (primary key (t.id))",
        "create table t (primary key (id) no inherit)",
        "create table t (exclude (id with =) not enforced)",
        "create table t (foreign key (id) references parent(id) no inherit)",
        "create table t (foreign key (period valid_at) references parent(id))",
        "create table t (foreign key (id, period valid_at, other) references parent(id))",
        "create table t (id int references parent(id, period valid_at))",
        "create table t (unique (id) deferrable not deferrable)",
        "create table t (unique (id) not deferrable initially deferred)",
        "create table t (check (id > 0) enforced not enforced)",
        "create table t (check (id > 0) nonsense)",
        "create table t (exclude ())",
        "create table t (exclude (id with))",
        "create table t (id int) partition by range (id collate)",
        "create table t (id int) partition by range (id desc)",
        "create table t (id int) partition by range (id nulls first)",
        "create table t (id int) partition by range (id int4_ops (option = true))",
        "create table t (id int) partition by range (id,)",
        "create table t (id int) partition by range (id + 1)",
        "create table t (id int) partition by range (t.id)",
        "create table t (id int) partition by range (lower(id) over ())",
        "create table t (id int) partition by range (id::bigint)",
        "create table t (id int, exclude (id + 1 with =))",
        "create table t (id int, exclude (t.id with =))",
        "create table t (id int, exclude (lower(id) over () with =))",
        "create table t (id int, exclude (id with plus))",
    ]);
}

#[test]
fn malformed_type_names_are_rejected_without_dropping_tokens() {
    assert_parse_errors(&[
        "create table t (value int garbage)",
        "create table t (value app..custom_type)",
        "create table t (value int(3))",
        "create table t (value numeric())",
        "create table t (value numeric(10,))",
        "create table t (value float(0))",
        "create table t (value float(54))",
        "create table t (value float(10, 20))",
        "create table t (value timestamp with zone)",
        "create table t (value int[foo])",
        "create table t (value int[-1])",
        "create table t (value int array[2][3])",
        "create table t (value interval year to day)",
        "create table t (value interval(1, 2))",
        "create table t (value setof)",
        "create function f(value app..custom_type) returns int language sql as 'select 1'",
        "create function f(value int garbage) returns int language sql as 'select 1'",
    ]);
}

#[test]
fn malformed_object_name_and_signature_lists_are_rejected() {
    assert_parse_errors(&[
        "drop table app.",
        "drop table app.items nonsense",
        "drop table app.items,",
        "drop role alice,",
        "drop owned alice",
        "drop owned by",
        "drop function f(int",
        "drop function f(int,)",
        "drop function f(value int default 1)",
        "drop function f(int) garbage",
        "drop function +(int, int)",
        "drop aggregate agg",
        "drop aggregate agg()",
        "drop aggregate +(int)",
        "drop function 'f'()",
        "drop function 123()",
        "drop operator +",
        "drop operator +(integer)",
        "drop operator +(none, none)",
        "drop operator plus(int, int)",
        "drop function schema..f(int)",
        "alter function f(int,) stable",
        "alter operator +(int,) set (restrict = join)",
        "alter operator + set (restrict = join)",
        "alter operator + set schema app",
        "alter operator + owner to alice",
        "alter operator plus(int, int) set (restrict = join)",
        "alter extension e add operator +",
        "alter extension e add operator plus(int, int)",
        "alter extension e add aggregate agg",
        "grant select on table app.items, to alice",
        "grant select on table app.items nonsense to alice",
        "grant execute on function f(int,) to alice",
        "grant execute on function +(int, int) to alice",
        "grant select on all tables in schema to alice",
        "reassign owned by alice, to bob",
    ]);
}

